package com.logatron.auth.application;
import com.logatron.auth.domain.PlatformRole;import com.logatron.auth.web.MeController.*;import com.logatron.catalog.persistence.*;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @Transactional(readOnly=true) public class MeService{private final AuthorizationService auth;private final ProjectRepository projects;private final EnvironmentRepository environments;public MeService(AuthorizationService auth,ProjectRepository projects,EnvironmentRepository environments){this.auth=auth;this.projects=projects;this.environments=environments;}public MeResponse me(Jwt jwt){var user=auth.authenticatedUser(jwt);var scope=auth.resolveScope(user);List<ProjectAccess> access=scope.projects().values().stream().map(p->{String name=projects.findById(p.projectId()).map(ProjectEntity::getName).orElse("Unknown");List<EnvironmentAccess> env=environments.findAllById(p.environmentIds()).stream().sorted(Comparator.comparing(EnvironmentEntity::getCode)).map(e->new EnvironmentAccess(e.getId(),e.getCode(),e.getName())).toList();return new ProjectAccess(p.projectId(),name,p.roles(),env);}).toList();Set<PlatformRole> roles=access.stream().flatMap(a->a.roles().stream()).collect(java.util.stream.Collectors.toSet());return new MeResponse(new UserView(user.id(),user.username(),user.displayName(),user.email()),roles,access);}}
